import{_ as s,o as n,c as e,a2 as l}from"./chunks/framework.CqGS6Fr9.js";const m=JSON.parse('{"title":"Справочник CLI","description":"","frontmatter":{"pageId":"admins/cli","contentRevision":2},"headers":[],"relativePath":"ru/admins/cli.md","filePath":"ru/admins/cli.md"}'),p={name:"ru/admins/cli.md"};function t(i,a,r,c,o,d){return n(),e("div",null,[...a[0]||(a[0]=[l(`<h1 id="справочник-cli" tabindex="-1">Справочник CLI <a class="header-anchor" href="#справочник-cli" aria-label="Permalink to &quot;Справочник CLI&quot;">​</a></h1><p>Применимость: Rimlink 0.8.1 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p>Утилита rimlink-tools имеет четыре корня: backup, restore, modpack, admin. Команды local backup/restore работают с диском; admin и операции публикации modpack обращаются к серверу.</p><p>Пример чтения: <code>rimlink-tools admin status --server https://play.example.org:25560 --token &lt;TOKEN&gt;</code>. Токен в аргументах виден истории shell и спискам процессов: не сохраняй команду с реальным секретом в тикетах/скриншотах. --insecure принимает недоверенный сертификат и пригоден лишь для изолированного теста.</p><p>Для полной точной арности используй --help соответствующего корня. Ниже перечислены все команды admin; команды модов и дисковой копии описаны в связанных руководствах. Идентификаторы числовые, дробные числа в CLI разбираются invariant culture (точка).</p><h2 id="cli-read-first" tabindex="-1">Безопасный первый сеанс CLI <a class="header-anchor" href="#cli-read-first" aria-label="Permalink to &quot;Безопасный первый сеанс CLI {#cli-read-first}&quot;">​</a></h2><p>Проверь --help, адрес HTTPS и доверие сертификату. Для удалённых admin-команд обязательны --server и --token; локальные backup/restore работают с --data и не используют HTTP. Перед любой мутацией прочитай status и players, найди постоянный playerId, затем player и actions.</p><p>Например, последовательность admin status → admin players → admin player 42 → admin actions не изменяет мир. Подставляй адрес/секрет оператора вне общего чата. Для wallet значение delta обязательно, несмотря на неоднозначные квадратные скобки help; отрицательное значение списывает средства. Не проверяй синтаксис реальной компенсацией.</p><p>Группы ниже сохраняют полный набор команд. Для необратимой операции заранее запиши цель, причину, backup и ожидаемый результат, затем проверь ответ и audit.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>wallet в текущей реализации требует delta, хотя краткая help-строка показывает её необязательной: для чтения баланса используй API GET economy/wallet/{id} или карточку игрока. raids cancel поддерживает --return для возврата пешек. Ошибка CLI/HTTP не доказывает отсутствие выполненной операции: сначала проверь состояние.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./api">Справочник REST API</a></li><li><a href="./modpacks">Управление набором модов</a></li><li><a href="./backup-recovery">Резервные копии и восстановление</a></li></ul><h2 id="reference" tabindex="-1">Все admin-команды <a class="header-anchor" href="#reference" aria-label="Permalink to &quot;Все admin-команды {#reference}&quot;">​</a></h2><p>Каждая строка следует после <code>rimlink-tools admin</code>; обязательны <code>--server URL --token TOKEN</code>, необязателен <code>--insecure</code> только для тестов. <code>&lt;...&gt;</code> — обязательный аргумент, <code>[...]</code> — необязательный, <code>|</code> — выбор. Причину с пробелами заключай в кавычки. Права и эффекты соответствуют одноимённому REST-маршруту; таблица API указывает минимальный scope.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>actions</span></span>
<span class="line"><span>archive &lt;playerId&gt;</span></span>
<span class="line"><span>archived [archived|restored|all]</span></span>
<span class="line"><span>auction cancel &lt;id&gt; [reason]</span></span>
<span class="line"><span>auctions</span></span>
<span class="line"><span>backup</span></span>
<span class="line"><span>backup-get &lt;name&gt; &lt;file&gt;</span></span>
<span class="line"><span>backups</span></span>
<span class="line"><span>ban &lt;playerId&gt; [days] [reason]</span></span>
<span class="line"><span>bans</span></span>
<span class="line"><span>broadcast &lt;text&gt;</span></span>
<span class="line"><span>chat [playerId]</span></span>
<span class="line"><span>colonies [playerId]</span></span>
<span class="line"><span>colony revoke &lt;ownerPlayerId&gt; &lt;memberPlayerId&gt;</span></span>
<span class="line"><span>config</span></span>
<span class="line"><span>economy freeze [reason]|unfreeze|stats</span></span>
<span class="line"><span>forbid list|add &lt;def...&gt;|remove &lt;def...&gt;</span></span>
<span class="line"><span>incidents list [playerId]|cancel &lt;id&gt; [reason]</span></span>
<span class="line"><span>influence</span></span>
<span class="line"><span>influence-archive-disable &lt;archiveId&gt; &lt;settlementId&gt; &lt;requestId&gt; &lt;worldId&gt; &lt;generation&gt; &lt;allianceId&gt; &lt;version&gt;</span></span>
<span class="line"><span>influence-archive-setting &lt;archiveId&gt;</span></span>
<span class="line"><span>influence-color &lt;allianceId&gt; &lt;worldId&gt; &lt;paletteIndex&gt; &lt;requestId&gt;</span></span>
<span class="line"><span>influence-disable &lt;settlementId&gt; &lt;requestId&gt; &lt;worldId&gt; &lt;generation&gt; &lt;allianceId&gt; &lt;version&gt;</span></span>
<span class="line"><span>influence-setting &lt;settlementId&gt;</span></span>
<span class="line"><span>kick &lt;playerId&gt; [reason]</span></span>
<span class="line"><span>live list [playerId]|end &lt;id&gt; [reason]</span></span>
<span class="line"><span>lots [playerId]</span></span>
<span class="line"><span>modpack</span></span>
<span class="line"><span>mute &lt;playerId&gt; &lt;minutes&gt;</span></span>
<span class="line"><span>online</span></span>
<span class="line"><span>parcels &lt;playerId&gt;</span></span>
<span class="line"><span>pardon &lt;banId&gt;</span></span>
<span class="line"><span>peaceful &lt;playerId&gt; on|off</span></span>
<span class="line"><span>player &lt;playerId&gt;</span></span>
<span class="line"><span>player-freeze &lt;playerId&gt; [reason]</span></span>
<span class="line"><span>player-unfreeze &lt;playerId&gt;</span></span>
<span class="line"><span>players [query]</span></span>
<span class="line"><span>procurement list [page]|cancel &lt;id&gt; [reason]</span></span>
<span class="line"><span>raids list [playerId]|cancel &lt;id&gt; [reason] [--return]|freeze [reason]|unfreeze|stats</span></span>
<span class="line"><span>recreateworld</span></span>
<span class="line"><span>refund lot|parcel &lt;id&gt;</span></span>
<span class="line"><span>removals &lt;playerId&gt;</span></span>
<span class="line"><span>rename &lt;playerId&gt; &lt;name&gt; [faction]</span></span>
<span class="line"><span>reset &lt;playerId&gt;</span></span>
<span class="line"><span>restore-colony &lt;archiveId&gt;</span></span>
<span class="line"><span>role &lt;playerId&gt; player|moderator|admin</span></span>
<span class="line"><span>rollback &lt;playerId&gt; &lt;version&gt;</span></span>
<span class="line"><span>saveall</span></span>
<span class="line"><span>saves &lt;playerId&gt;</span></span>
<span class="line"><span>say &lt;author&gt; &lt;text&gt;</span></span>
<span class="line"><span>shop &lt;playerId&gt;</span></span>
<span class="line"><span>shutdown &lt;seconds&gt; [reason]</span></span>
<span class="line"><span>status</span></span>
<span class="line"><span>trade cancel &lt;id&gt; [reason]</span></span>
<span class="line"><span>trades [playerId]</span></span>
<span class="line"><span>unmute &lt;playerId&gt;</span></span>
<span class="line"><span>wallet &lt;playerId&gt; &lt;+n|-n&gt; [reason]</span></span></code></pre></div><p><code>wallet</code> обязательно принимает delta: несмотря на квадратные скобки в текущем --help, без него операция не является просмотром баланса. <code>raids cancel --return</code> просит возврат пешек; не используй как произвольное возмещение. Для influence сначала получи setting: requestId и context/version нужны для контроля повторов и устаревшего состояния. <code>reset</code>, <code>recreateworld</code>, rollback и restore меняют/уничтожают данные — сначала резервная копия и подтверждение.</p><h3 id="локальные-команды-и-модпак" tabindex="-1">Локальные команды и модпак <a class="header-anchor" href="#локальные-команды-и-модпак" aria-label="Permalink to &quot;Локальные команды и модпак&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rimlink-tools backup --data &lt;dir&gt; [--out &lt;archive.tar.zst&gt;]</span></span>
<span class="line"><span>rimlink-tools restore --data &lt;dir&gt; --from &lt;archive.tar.zst&gt;</span></span>
<span class="line"><span>rimlink-tools modpack import --from &lt;ModsConfig.xml&gt; [--mods-dir &lt;folders...&gt;] [--dry-run]</span></span>
<span class="line"><span>rimlink-tools modpack defs --mods-dir &lt;folders...&gt; [--dry-run]</span></span>
<span class="line"><span>rimlink-tools modpack configs import --config-dir &lt;dir&gt; --mods-dir &lt;folders...&gt; --mod &lt;packageIds...&gt; [--dry-run]</span></span>
<span class="line"><span>rimlink-tools modpack configs import --clear [--dry-run]</span></span>
<span class="line"><span>rimlink-tools modpack configs list --server &lt;URL&gt; --token &lt;TOKEN&gt;</span></span>
<span class="line"><span>rimlink-tools modpack package requirements --output &lt;new-file&gt; --server &lt;URL&gt; --token &lt;TOKEN&gt;</span></span>
<span class="line"><span>rimlink-tools modpack package pack --source &lt;prepared-dir&gt; --requirements &lt;file&gt; --output &lt;new-dir&gt;</span></span>
<span class="line"><span>rimlink-tools modpack package publish --from &lt;dir&gt; --confirm-redistribution [--confirm-public] [--confirm-shared-settings] --server &lt;URL&gt; --token &lt;TOKEN&gt;</span></span>
<span class="line"><span>rimlink-tools modpack package status --server &lt;URL&gt; --token &lt;TOKEN&gt;</span></span>
<span class="line"><span>rimlink-tools modpack package unpublish --server &lt;URL&gt; --token &lt;TOKEN&gt;</span></span></code></pre></div><p>Для import/defs/configs import без --dry-run требуются --server/--token; --insecure доступен для HTTP-клиентов. Backup безопасен при работающем сервере; restore требует остановленного. Pack работает офлайн с отдельной разрешённой коллекцией, никогда с корнем игры; новые выходные пути не должны существовать. configs import делится только выбранными модами ниже Rimlink; проверь файлы на секреты. requirements/status читают сервер; publish/unpublish меняют доступность пакета, подтверждения нельзя добавлять автоматически.</p>`,21)])])}const u=s(p,[["render",t]]);export{m as __pageData,u as default};
